/**
 * Structured, validated actions performed by the Action Engine.
 *
 * The parser and analyzer produce Action objects. The DOM Controller
 * applies them using safe DOM APIs. KATOCHI never executes arbitrary
 * JavaScript generated by an AI — only these validated actions exist.
 */

import type { Target } from './context';

/** Discriminator shared by every action. */
export type ActionType =
  | 'changeBackground'
  | 'changeTextColor'
  | 'changeTypography'
  | 'createButton'
  | 'createSearchBar'
  | 'glitchEffect'
  | 'shakeEffect'
  | 'chaosMode'
  | 'undo'
  | 'exorcise';

interface ActionBase {
  type: ActionType;
}

/** Change the background color of a target. */
export interface ChangeBackgroundAction extends ActionBase {
  type: 'changeBackground';
  target: Target;
  /** CSS color value, e.g. "#ff0000" or "red". */
  color: string;
}

/** Change the text color of a target. */
export interface ChangeTextColorAction extends ActionBase {
  type: 'changeTextColor';
  target: Target;
  color: string;
}

/** Change the typography of a target. */
export interface ChangeTypographyAction extends ActionBase {
  type: 'changeTypography';
  target: Target;
  /** CSS font-family stack, e.g. "Arial, sans-serif". */
  fontFamily?: string;
  /** CSS font-size, e.g. "20px". */
  fontSize?: string;
  /** CSS font-weight, e.g. "bold" or "700". */
  fontWeight?: string;
}

/** Create a button on the page. */
export interface CreateButtonAction extends ActionBase {
  type: 'createButton';
  target: Target;
  label: string;
}

/** Create a search bar on the page. */
export interface CreateSearchBarAction extends ActionBase {
  type: 'createSearchBar';
  target: Target;
  placeholder?: string;
}

/** Apply the glitch effect to a target for a fixed duration. */
export interface GlitchEffectAction extends ActionBase {
  type: 'glitchEffect';
  target: Target;
  /** Effect duration in milliseconds. */
  durationMs: number;
}

/** Apply the shake effect to a target for a fixed duration. */
export interface ShakeEffectAction extends ActionBase {
  type: 'shakeEffect';
  target: Target;
  /** Effect duration in milliseconds. */
  durationMs: number;
}

/** Run Chaos Mode using a fixed effect set for a fixed duration. */
export interface ChaosModeAction extends ActionBase {
  type: 'chaosMode';
  /** Total chaos duration in milliseconds. */
  durationMs: number;
}

/** Undo the most recent KATOCHI modification. */
export interface UndoAction extends ActionBase {
  type: 'undo';
}

/** Exorcise the mascot: revert every KATOCHI-owned modification. */
export interface ExorciseAction extends ActionBase {
  type: 'exorcise';
}

/** The complete set of actions the engine can perform. */
export type Action =
  | ChangeBackgroundAction
  | ChangeTextColorAction
  | ChangeTypographyAction
  | CreateButtonAction
  | CreateSearchBarAction
  | GlitchEffectAction
  | ShakeEffectAction
  | ChaosModeAction
  | UndoAction
  | ExorciseAction;
